/* monitor.c - the whole trusted core: read-only rules, no allocation, no libc state */
static const struct rule policy[] = {
    { ROLE_AUDITOR, ACT_READ,  OBJ_LEDGER, 1 },  /* subject, action, object, allow */
    { ROLE_AUDITOR, ACT_WRITE, OBJ_LEDGER, 0 },
};

int monitor_check(uint32_t subject, enum action a, enum object o) {
    for (size_t i = 0; i < sizeof policy / sizeof *policy; i++)
        if (policy[i].subject == subject && policy[i].action == a && policy[i].object == o)
            return policy[i].allow;
    return 0;                                /* fail closed: unknown triple denied */
}

