/* attach the monitor to the thread, then never run without it */
prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0);
struct sock_fprog prog = { .len = (unsigned short)(sizeof allow / sizeof *allow),
                           .filter = allow };      /* allow-list, never a deny-list */
if (syscall(SYS_seccomp, SECCOMP_SET_MODE_FILTER,
            SECCOMP_FILTER_FLAG_TSYNC, &prog) != 0)
    abort();                                       /* no monitor, no execution */

int ruleset = syscall(SYS_landlock_create_ruleset, &attr, sizeof attr, 0);
syscall(SYS_landlock_add_rule, ruleset, LANDLOCK_RULE_PATH_BENEATH, &rule, 0);
syscall(SYS_landlock_restrict_self, ruleset, 0);   /* inherited by every child */
